export function SourceFooter({
  source,
  url,
  marginTop = 12,
  measure = false,
}: {
  source?: string;
  url?: string;
  marginTop?: number;
  measure?: boolean;
}) {
  const input = source?.trim();
  const key = input?.toLowerCase();
  const brand = brands.find(item => item.aliases.some(([alias]) => alias === key));
  const label = brand?.aliases.find(([alias]) => alias === key)?.[1] ?? input;
  const address = url?.trim();
  if (!label && !address) return null;
  return (
    <div
      data-measure={measure || undefined}
      style={{
        display: 'flex',
        alignItems: 'center',
        minWidth: 0,
        width: measure ? undefined : '100%',
        flexShrink: 0,
        gap: 12,
        borderTop: '0.5px solid ' + colors.border,
        marginTop,
        paddingTop: 10,
        color: colors.muted,
        ...typography.meta,
      }}
    >
      {label && (
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            gap: 6,
            minHeight: 18,
            minWidth: 0,
            flexShrink: 0,
            maxWidth: measure ? undefined : address ? '70%' : '100%',
            color: colors.ink,
            fontWeight: 700,
          }}
        >
          {brand && (
            <svg width={brand.width} height={brand.height} viewBox={brand.viewBox} style={{ flexShrink: 0 }}>
              <path d={brand.path} fill={brand.color} />
            </svg>
          )}
          <div
            style={{
              display: 'block',
              minWidth: 0,
              whiteSpace: 'nowrap',
              overflow: 'hidden',
              textOverflow: 'ellipsis',
            }}
          >
            {label}
          </div>
        </div>
      )}
      {address && (
        <div
          style={{
            display: 'flex',
            minWidth: 0,
            flexGrow: measure ? 0 : 1,
            flexShrink: measure ? 0 : 1,
            justifyContent: label ? 'flex-end' : 'flex-start',
          }}
        >
          <div
            style={{
              display: 'block',
              minWidth: 0,
              maxWidth: measure ? undefined : '100%',
              whiteSpace: 'nowrap',
              overflow: 'hidden',
              textOverflow: 'ellipsis',
            }}
          >
            {address}
          </div>
        </div>
      )}
    </div>
  );
}
